const baseUrl = process.env.NEXT_PUBLIC_BASE_URL ?? 'http://localhost:3000'

// Good example: parallel data fetching
async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json()),
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json()),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json()),
    ])

    return { analytics, notifications, settings }
  } catch {
    // Return mock data for build time
    return {
      analytics: { pageViews: 0, visitors: 0 },
      notifications: [] as { id: number; message: string }[],
      settings: { theme: 'light' },
    }
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData()

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <p>Page views: {analytics.pageViews}</p>
        <p>Visitors: {analytics.visitors}</p>
      </section>

      <section>
        <h3>Notifications</h3>
        {notifications.length === 0 ? (
          <p>No notifications</p>
        ) : (
          <ul>
            {notifications.map((notification) => (
              <li key={notification.id}>{notification.message}</li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
      </section>
    </div>
  )
}

